CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE app_users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), oidc_subject text UNIQUE NOT NULL, email text UNIQUE NOT NULL, display_name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE stations (id text PRIMARY KEY, name text NOT NULL, location_code text NOT NULL, online boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE chargers (id text PRIMARY KEY, station_id text NOT NULL REFERENCES stations(id), connector text NOT NULL, max_power_kw numeric(8,2) NOT NULL CHECK(max_power_kw>0), power_source text NOT NULL, status text NOT NULL DEFAULT 'available', ocpp_identity text UNIQUE NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE vehicles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES app_users(id), registration text NOT NULL, vehicle_type text NOT NULL CHECK(vehicle_type IN ('car','bike','scooter')), battery_capacity_kwh numeric(8,2) NOT NULL CHECK(battery_capacity_kwh>0), connector text NOT NULL, max_charge_rate_kw numeric(8,2) NOT NULL, UNIQUE(user_id,registration));
CREATE TABLE tariffs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), station_id text NOT NULL REFERENCES stations(id), rate_per_kwh numeric(10,2) NOT NULL, solar_discount_percent numeric(5,2) NOT NULL DEFAULT 0, valid_from timestamptz NOT NULL, valid_until timestamptz);
CREATE TABLE sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES app_users(id), vehicle_id uuid NOT NULL REFERENCES vehicles(id), charger_id text NOT NULL REFERENCES chargers(id), status text NOT NULL, current_soc numeric(5,2), target_soc numeric(5,2) NOT NULL, maximum_budget numeric(10,2) NOT NULL, departure_time timestamptz, energy_kwh numeric(10,3) NOT NULL DEFAULT 0, cost numeric(10,2) NOT NULL DEFAULT 0, solar_percent numeric(5,2) NOT NULL DEFAULT 0, version bigint NOT NULL DEFAULT 0, started_at timestamptz NOT NULL DEFAULT now(), ended_at timestamptz);
CREATE TABLE meter_samples (id bigserial PRIMARY KEY, session_id uuid NOT NULL REFERENCES sessions(id), sampled_at timestamptz NOT NULL DEFAULT now(), soc numeric(5,2), power_kw numeric(9,3), energy_kwh numeric(10,3), cost numeric(10,2), solar_percent numeric(5,2));
CREATE INDEX meter_samples_session_time_idx ON meter_samples(session_id,sampled_at DESC);
CREATE TABLE queue_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), station_id text NOT NULL REFERENCES stations(id), user_id uuid NOT NULL REFERENCES app_users(id), vehicle_id uuid NOT NULL REFERENCES vehicles(id), urgency text NOT NULL, score numeric(10,2) NOT NULL, state text NOT NULL DEFAULT 'waiting', arrived_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE solar_samples (id bigserial PRIMARY KEY, station_id text NOT NULL REFERENCES stations(id), sampled_at timestamptz NOT NULL DEFAULT now(), output_kw numeric(9,3) NOT NULL, stored_kwh numeric(10,3) NOT NULL, grid_kw numeric(9,3) NOT NULL);
CREATE TABLE emergency_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), station_id text NOT NULL REFERENCES stations(id), session_id uuid REFERENCES sessions(id), paused_session_id uuid REFERENCES sessions(id), reason text NOT NULL, compensation_credit numeric(10,2) NOT NULL DEFAULT 50, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid UNIQUE NOT NULL REFERENCES sessions(id), subtotal numeric(10,2) NOT NULL, discount numeric(10,2) NOT NULL DEFAULT 0, total numeric(10,2) NOT NULL, currency char(3) NOT NULL DEFAULT 'INR', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id bigserial PRIMARY KEY, request_id text NOT NULL, actor_subject text NOT NULL, action text NOT NULL, resource_type text NOT NULL, resource_id text, payload jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency_keys (actor_subject text NOT NULL, operation text NOT NULL, key text NOT NULL, response_code integer NOT NULL, response_body jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(actor_subject,operation,key));
